function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length < 3 || s.length > 100000) return 's needs 3 to 100000 characters.';
  if (!/^[01]+$/.test(s)) return "s may contain only '0' and '1'.";
  return null;
}

