function numberOfWays(s) {
  const n = s.length;
  let totalZeros = 0;
  for (let i = 0; i < n; i++) {
    if (s[i] === '0') totalZeros++;
  }
  const totalOnes = n - totalZeros;
  let zerosLeft = 0;
  let onesLeft = 0;
  let ways = 0;
  for (let i = 0; i < n; i++) {
    if (s[i] === '0') {
      const onesRight = totalOnes - onesLeft;
      ways += onesLeft * onesRight;
      zerosLeft++;
    } else {
      const zerosRight = totalZeros - zerosLeft;
      ways += zerosLeft * zerosRight;
      onesLeft++;
    }
  }
  return ways;
}

