function generate(rand, size) {
  const n = size === 'large' ? 10000 : 3 + Math.floor(rand() * 10);
  // A per-input bias gives strings that range from nearly uniform to well mixed.
  const bias = rand();
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < bias ? '1' : '0';
  return [s];
}
